# Fonsi Third Place Finder - Pre-Launch Feature Batch
# Adds: listing detail pages, "I'm interested" button, WhatsApp share,
# and the encouragement quote widget.
# Uses -LiteralPath throughout so folder names like [id] (a Next.js
# dynamic route folder) are treated literally, not as wildcards.

$projectRoot = "C:\Users\HP\Projects\Fonsi_Third_Place_Finder"

function Write-FileFromBase64($RelativePath, $Base64Content) {
    $fullPath = Join-Path $projectRoot $RelativePath
    $dir = Split-Path $fullPath -Parent
    if (!(Test-Path -LiteralPath $dir)) {
        New-Item -ItemType Directory -Force -Path $dir | Out-Null
    }
    $bytes = [System.Convert]::FromBase64String($Base64Content)
    [System.IO.File]::WriteAllBytes($fullPath, $bytes)
    Write-Host "Written: $RelativePath" -ForegroundColor Green
}


Write-FileFromBase64 "supabase\\migrations\\002_interested_counter.sql" ""

Write-FileFromBase64 "app\\api\\listings\\[id]\\interested\\route.ts" ""

Write-FileFromBase64 "components\\listings\\InterestedButton.tsx" ""

Write-FileFromBase64 "components\\listings\\WhatsAppShareButton.tsx" ""

Write-FileFromBase64 "app\\listings\\[id]\\page.tsx" ""

Write-FileFromBase64 "components\\QuoteWidget.tsx" ""

Write-FileFromBase64 "components\\listings\\ListingCard.tsx" ""

Write-FileFromBase64 "components\\listings\\ListingGrid.tsx" ""

Write-FileFromBase64 "app\\page.tsx" ""


Write-Host ""
Write-Host "Pre-launch features added. Now run:" -ForegroundColor Cyan
Write-Host "  Remove-Item -Recurse -Force `"$projectRoot\.next`"" -ForegroundColor Yellow
Write-Host "  cd `"$projectRoot`"" -ForegroundColor Yellow
Write-Host "  npm run dev" -ForegroundColor Yellow
Write-Host ""
Write-Host "Also run the new SQL migration (002_interested_counter.sql) in Supabase's SQL Editor before testing the interested button." -ForegroundColor Cyan
